mapper.delete:
DELETE FROM "MEMBER_ACTION"
WHERE SENDER_NO = #{myNo}
  AND RECEIVER_NO = #{targetNo}
  AND ACTION_TYPE = 'LIKE'

mapper.insert:
INSERT INTO "MEMBER_ACTION" (
	ACTION_NO, ACTION_TYPE, INPUT_TYPE, ACTION_DATE, SENDER_NO, RECEIVER_NO
) VALUES (
	SEQ_ACTION_NO.NEXTVAL, #{actionType}, #{inputType}, SYSDATE, #{senderNo}, #{receiverNo}
)

mapper.select:
SELECT COUNT(*) FROM "MEMBER_ACTION"
WHERE SENDER_NO = #{targetNo}
  AND RECEIVER_NO = #{myNo}
  AND ACTION_TYPE = 'LIKE'
  AND EXISTS (
	SELECT 1 FROM "MEMBER_ACTION"
	WHERE SENDER_NO = #{myNo}
	  AND RECEIVER_NO = #{targetNo}
	  AND ACTION_TYPE = 'LIKE'
  )
